       ).toEqual(dataset);
       expect(
         h.updates.some((update) => update.id === run.id && update.status === "completed"),
       ).toBe(true);
       expect(h.fetchImpl).not.toHaveBeenCalled();
       expect(seams.unrelatedBlockRun).not.toHaveBeenCalled();
     },
